      "E": "360 / 9 = 40, 9 hız için 40 gün doğrudur, ifade doğrudur."
    },
    "hesap_adimlari": [
      "Stok devir hızı × stokta kalma süresi = 360",
      "6 × 60 = 360 → doğru",
      "6 × 70 = 420 → 360’a eşit değil → yanlıştır"
    ]
  },
  "kaynaklar": [
    {
      "mevzuat": "Genel bilgi — Finansal Tablolar ve Analizi",
      "madde": "-",
      "parca": "P1",
      "alinti": "Stok devir hızı ile stokta kalma süresi arasında: Devir Hızı × Kalma Süresi = Yıl Günü (360) ilişkisi vardır. Bu, finansal analizde standart bir hesaplama yöntemidir."
    }
  ],
  "gecerlilik": {
    "baslangic": "2026-01-01",
    "bitis": null,
    "yila_bagli_tutar": false
  },
  "dogrulama": {
