    "B": "%50",
    "C": "%60",
    "D": "%80",
    "E": "%100"
  },
  "dogru": "B",
  "aciklama": {
    "dogru_neden": "Trend yüzdesi, her yılın tutarının baz yıl (2022) tutarına oranıdır. 2022’de brüt satış kârının trend yüzdesi: 480 / 480 × 100 = %100. 2026’da brüt satış kârının trend yüzdesi: 720 / 480 × 100 = %150. Değişim: %150 – %100 = %50 artmıştır. Püf noktaları: Soruda hem dikey analiz hem trend analizi karıştırılmış izlenimi verilir; ancak kullanılan yöntem pure trend analizidir (her kalemin kendi baz yılına göre indekslenmesi). Brüt satış kârı trendi, net satış trendinden bağımsız hesaplanır. Baz yıl oranı %100'dür, artış bu temele göre değerlendirilir.",
    "celdiriciler": {
      "A": "Yanlış kalemler kullanılarak net satışların trendi hesaplanmış olabilir: 2.400 / 1.600 = 1,5 → %150 artış değil, %50 artış olur; ancak soru brüt satış kârının trend artışını sorar.",
      "C": "720 - 480 = 240, bu farkın 480'e oranı %50 değilmiş gibi yanlış hesaplanmış ve %60 olarak kabul edilmiş olabilir.",
      "D": "2026 net satış trendi: 2.400 / 1.600 × 100 = %150; 2022’de %100 olduğundan %50 artış. %80, bu değerle karıştırılmış olabilir.",
      "E": "Brüt kâr tutarında 480'den 720'e artış %50'dir; %100 artış sanılması, 480'in iki katı (960) ile karşılaştırılması sonucu olabilir."
    },
    "hesap_adimlari": [
      "2022 brüt satış kârı trend yüzdesi: (480 / 480) × 100 = %100",
      "2026 brüt satış kârı trend yüzdesi: (720 / 480) × 100 = %150",
      "Trend yüzde artış miktarı: %150 – %100 = %50"
    ]
  },
  "kaynaklar": [
