      "E": "100, devir hızının 3,6 kez alınmasıyla bulunur; örnek: 800 / 200 = 4 yerine 720 / 200 = 3,6 ve 360 / 3,6 = 100 gibi bir hata olabilir."
    },
    "hesap_adimlari": [
      "Ortalama yarı mamul stok: (180 + 220) / 2 = 200 bin ₺",
      "Devir hızı: 800 / 200 = 4 kez",
      "Stokta kalma süresi: 360 / 4 = 90 gün"
