asama1.T041-1:
{
  "tip": "uygulama",
  "zorluk": 3,
  "soru_bicimi": "standart",
  "kok": "193 sayılı Gelir Vergisi Kanunu'na göre dar mükellef gerçek kişi olan bir yazar, Türkiye'de telif hakkı satışı dolayısıyla 2026 yılında 80.000 TL tutarında ödeme almıştır. Bu ödeme üzerinden tevkif edilen gelir vergisi oranı %20'dir. Yazarın bu geliriyle ilgili olarak aşağıdaki ifadelerden hangisi doğrudur?",
  "secenekler": {
    "A": "Yazar, bu geliri için münferit beyanname verme yükümlülüğü taşımaz çünkü gelir tamamen tevkifatla vergilendirilmiştir.",
    "B": "Yazar, bu geliri için 15 gün içinde münferit beyanname vermek zorundadır çünkü dar mükellef gerçek kişidir.",
    "C": "Yazar, bu geliri yıllık beyannamesine eklemelidir çünkü tevkifatla vergilendirilse dahi beyan gerekir.",
    "D": "Yazar, tevkif edilen tutarın %15'ini yıllık beyannameyle mahsup edebilir, kalan %5'ini iade alabilir.",
    "E": "Yazar, bu gelir için vergi muafiyetine tabidir çünkü yazarlık geliri özel istisnadır."
  },
  "dogru": "A",
  "aciklama": {
    "dogru_neden": "GVK md. 101'in son fıkrasına göre, geliri telif ve patent haklarının satışından ibaret olan ve tamamı üzerinden tevkif suretiyle gelir vergisi ödemiş bulunan dar mükellefiyete tabi kimselerin bu gelirleri için münferit beyanname vermeleri ihtiyaridir. Bu, yükümlülük olmadığını, dolayısıyla beyanname vermemenin meşru olduğunu ifade eder. Püf noktaları: Dar mükellef olmak, gelirin telif satışından gelmesi ve tam tevkifat uygulanması bu istisnayı getirir. Ayrıca GVK Geçici Madde 67/7'de bu tür kazançlar için gerçek kişilerce yıllık veya münferit beyanname verilmediği açıkça belirtilmiştir.",
    "celdiriciler": {
      "B": "15 gün kuralı, tevkifat yapılmamış kazançlar için geçerlidir (GVK md. 101). Bu ödeme tevkifatlıdır ve dar mükellef için özel hali vardır.",
      "C": "Tevkifatlı ve tam kapsamda vergilendirilen dar mükellef telif gelirleri, GVK md. 101'e göre beyana dahil edilmez.",
      "D": "Mahsup, yıllık beyanname verildiğinde mümkündür. Ancak bu gelirler için beyanname verilmez. Ayrıca %20 tevkifat kesin, mahsup söz konusu değildir.",
      "E": "Yazarlık geliri genel olarak vergiden istisna değildir; ancak tevkifat uygulandığında beyan yükümlülüğü ortadan kalkar."
    }
  },
  "kaynaklar": [
    {
      "mevzuat": "193 sayılı Gelir Vergisi Kanunu",
      "madde": "md. 101",
      "parca": "P12",
      "alinti": "Geliri telif ve patent haklarının satışından ibaret olan ve tamamı üzerinden tevkif suretiyle gelir vergisi ödemiş bulunan dar mükellefiyete tabi kimselerin bu gelirleri için münferit beyanname vermeleri ihtiyaridir."
    },
    {
      "mevzuat": "193 sayılı Gelir Vergisi Kanunu",
      "madde": "Geçici Madde 67/7",
      "parca": "P10",
      "alinti": "(1), (2), (3) ve (4) numaralı fıkra hükümleri uyarınca tevkifata tâbi tutulan kazançlar için gerçek kişilerce yıllık veya münferit beyanname verilmez. Diğer gelirler dolayısıyla verilecek yıllık beyannameye bu gelirler dahil edilmez."
    }
  ],
