asama1.T043-0:
{
  "tip": "uygulama",
  "zorluk": 3,
  "soru_bicimi": "standart",
  "kok": "Türkiye’de mukim (H) Mühendislik A.Ş., 10 Mart 2026’da Dubai merkezli bir şirkete 120.000 USD bedelli proje danışmanlığı hizmeti sunmuştur. Hizmetin tamamı Dubai’de yürütülmüş, fatura 10 Mart’ta düzenlenmiştir ve bedel henüz Türkiye’ye aktarılmamıştır. (H) A.Ş., hizmet ihracatı istisnası kapsamında KDV beyannamesine bu işlemi 302 kodu ile bildirmiştir. Ancak, hizmetin Türkiye'deki bir ofisinde yürütüldüğünü belirten bir idari inceleme raporu düzenlenmiştir. Bu durumda, istisna uygulaması ve KDV iadesi ile ilgili aşağıdakilerden hangisi doğrudur?",
  "secenekler": {
    "A": "Hizmet ihracatı istisnası geçerlidir çünkü fatura yurtdışındaki müşteri adına düzenlenmiştir.",
    "B": "İstisna uygulanamaz çünkü hizmet bedeli henüz Türkiye’ye aktarılmamıştır.",
    "C": "İstisna uygulanamaz çünkü hizmetin Türkiye’de yürütülmesi, hizmetten yurtdışında faydalanılma koşulunu bozar.",
    "D": "İstisna geçerlidir çünkü hizmet yurtdışındaki müşteri için yapılmıştır ve fatura yurtdışında kullanılmaktadır.",
    "E": "KDV iadesi mahsuben yapılamaz ancak nakden iade talep edilebilir."
  },
  "dogru": "C",
  "aciklama": {
    "dogru_neden": "KDVK md. 11/1-a ve KDV Genel Uygulama Tebliği 2.1’e göre, hizmet ihracatı istisnasının uygulanabilmesi için hizmetin yurtdışında faydalanılması gerekir. Burada hizmetin Türkiye'de yürütüldüğü tespit edilmişse, hizmetten yurtdışında faydalanılma kriteri sağlanmaz. Dolayısıyla istisna uygulanamaz. Püf noktaları: fatura düzenlemesi ve müşteri yurtdışında olsa bile, hizmetin fiili ifa yeri kriteri ihlal edilirse istisna geçersizdir.",
    "celdiriciler": {
      "A": "Faturanın yurtdışındaki müşteri adına düzenlenmesi, hizmetin yurtdışında faydalanıldığını kanıtlamaz; bu yalnızca bir belgeleme koşuludur.",
      "B": "İstisnanın geçerliliği, bedelin Türkiye’ye aktarılmasına bağlı değildir; bu, yalnızca iadenin yapılabilmesi için gereklidir.",
      "D": "Hizmetin yurtdışındaki müşteri için yapılması yeterli değildir; hizmetin Türkiye'deki faaliyetlerle ilgili olmaması ve yurtdışında faydalanılması gerekir.",
      "E": "İstisna geçerli değilse, iade talebi de gündeme gelmez; ilk adım istisnanın uygulanabilirliğidir."
    }
  },
  "kaynaklar": [
    {
      "mevzuat": "3065 sayılı Katma Değer Vergisi Kanunu",
      "madde": "md. 11/1-a",
      "parca": "P1",
      "alinti": "3065 sayılı Kanunun (11/1-a) maddesi kapsamında bir hizmetin KDV’den istisna olabilmesi için, aynı Kanunun (12/2) nci maddesine göre; Hizmetin yurtdışındaki bir müşteri için yapılması, Hizmetten yurtdışında faydalanılması, gerekir."
    },
    {
      "mevzuat": "KDV Genel Uygulama Tebliği",
      "madde": "2.1",
      "parca": "P1",
      "alinti": "Hizmetten yurtdışında faydalanılmasından kasıt, Türkiye’de yurtdışındaki müşteri için yapılan hizmetin, müşterinin yurtdışındaki iş, işlem ve faaliyetleri ile ilgili olması; Türkiye'deki faaliyetleri ile ilisi bulunmamasıdır."
    }
  ],
  "gecerlilik": {
    "baslangic": "2026-01-01",
